"""Convert a UTF-8 CSV (header: item,quantity) to a JSON array.

Reads the input filename from sys.argv[1] and writes exactly one JSON value
(the array) to stdout. The input file is only read, never modified.
"""
from __future__ import annotations

import csv
import json
import re
import sys

_WS_RUN = re.compile(r"\s+")


def normalize_name(name: str) -> str:
    """Collapse all whitespace runs to single spaces, strip, then casefold."""
    return _WS_RUN.sub(" ", name).strip().casefold()


def parse_quantity(raw: str) -> int:
    """Blank quantity means 1; otherwise a nonnegative base-10 integer."""
    s = raw.strip()
    if s == "":
        return 1
    value = int(s, 10)
    if value < 0:
        raise ValueError(f"negative quantity: {raw!r}")
    return value


def convert(text: str) -> list[dict]:
    totals: dict[str, int] = {}
    reader = csv.DictReader(io_string_lines(text))
    for row in reader:
        if row is None:
            continue
        item_raw = row.get("item") or ""
        qty_raw = row.get("quantity") or ""
        name = normalize_name(item_raw)
        if name == "":
            continue  # skip empty normalized names
        try:
            qty = parse_quantity(qty_raw)
        except ValueError:
            continue  # not a nonnegative base-10 integer -> skip
        totals[name] = totals.get(name, 0) + qty
    return [{"item": n, "quantity": totals[n]} for n in sorted(totals)]


def io_string_lines(text: str):
    """Yield lines while preserving exact bytes/whitespace (csv needs an iterable)."""
    return text.splitlines(keepends=False)


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2
    with open(argv[1], "r", encoding="utf-8", newline="") as f:
        text = f.read()
    result = convert(text)
    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))"}

